import pandas as pd
from typing import Optional

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Build a dict of target_state for fast lookup
    state_dict = {}
    if not target_state.empty:
        for _, row in target_state.iterrows():
            oid = row["order_id"]
            state_dict[oid] = {
                "status": row["status"],
                "amount": row["amount"],
                "last_seq": row["last_seq"]
            }

    # Remove duplicates by seq (at-least-once delivery)
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first")

    # Track last applied event (by seq) for each order that becomes deleted
    last_delete_seq = {}

    # Process events in seq order
    if not cdc_events.empty:
        cdc_events = cdc_events.sort_values("seq")

        for _, event in cdc_events.iterrows():
            oid = event["order_id"]
            seq = event["seq"]
            op = event["op"]

            # Replay guard: skip if order exists in target_state and seq <= last_seq
            if oid in state_dict and seq <= state_dict[oid]["last_seq"]:
                continue

            # Apply the event
            if op == "I":
                # Insert or update
                state_dict[oid] = {
                    "status": event["status"],
                    "amount": event["amount"],
                    "last_seq": seq
                }
                # Clear any tombstone marker since row now exists
                last_delete_seq.pop(oid, None)

            elif op == "U":
                # Update
                if oid not in state_dict:
                    # Create new row
                    state_dict[oid] = {
                        "status": event["status"],
                        "amount": event["amount"],
                        "last_seq": seq
                    }
                    last_delete_seq.pop(oid, None)
                else:
                    # Update existing row
                    state_dict[oid]["status"] = event["status"]
                    # NULL amount in update means leave unchanged
                    if pd.notna(event["amount"]):
                        state_dict[oid]["amount"] = event["amount"]
                    state_dict[oid]["last_seq"] = seq
                    last_delete_seq.pop(oid, None)

            elif op == "D":
                # Delete
                if oid in state_dict:
                    # Row exists, delete it
                    del state_dict[oid]
                    last_delete_seq[oid] = seq
                else:
                    # Row doesn't exist, no-op
                    # But if this is the first time we see this order and it's a D,
                    # we still need to track it for tombstones
                    last_delete_seq[oid] = seq

    # Build new_state
    new_state_rows = []
    for oid in sorted(state_dict.keys()):
        entry = state_dict[oid]
        new_state_rows.append({
            "order_id": oid,
            "status": entry["status"],
            "amount": entry["amount"],
            "last_seq": entry["last_seq"]
        })
    new_state = pd.DataFrame(new_state_rows, columns=["order_id", "status", "amount", "last_seq"])
    if new_state.empty:
        new_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])

    # Build tombstones: orders whose last applied event is D
    tombstone_rows = []
    for oid in sorted(last_delete_seq.keys()):
        # Only include if the order doesn't exist in final state
        # (i.e., the last applied event left it deleted)
        if oid not in state_dict:
            tombstone_rows.append({
                "order_id": oid,
                "deleted_seq": last_delete_seq[oid]
            })

    tombstones = pd.DataFrame(tombstone_rows, columns=["order_id", "deleted_seq"])
    if tombstones.empty:
        tombstones = pd.DataFrame(columns=["order_id", "deleted_seq"])

    return {
        "new_state": new_state,
        "tombstones": tombstones
    }
